import unittest

from journal import add, state, active


def v(event_id, revision, operation, fields):
    return {"event_id": event_id, "revision": revision,
            "operation": operation, "fields": fields}


class AddTests(unittest.TestCase):
    def test_added_returns_new_list_and_keeps_original(self):
        original = []
        journal, status = add(original, v("e1", 1, "create", {"start": 1, "length": 2}))
        self.assertEqual(status, "added")
        self.assertEqual(original, [])
        self.assertEqual(len(journal), 1)
        self.assertIsNot(journal, original)

    def test_duplicate(self):
        version = v("e1", 1, "create", {"start": 1, "length": 2})
        journal, _ = add([], version)
        journal2, status = add(journal, dict(version))
        self.assertEqual(status, "duplicate")
        self.assertEqual(journal2, journal)

    def test_conflict_keeps_journal(self):
        journal, _ = add([], v("e1", 1, "create", {"start": 1, "length": 2}))
        journal2, status = add(journal, v("e1", 1, "create", {"start": 9, "length": 2}))
        self.assertEqual(status, "conflict")
        self.assertEqual(journal2, journal)

    def test_same_revision_different_event_ok(self):
        journal, _ = add([], v("e1", 1, "create", {}))
        journal, status = add(journal, v("e2", 1, "create", {}))
        self.assertEqual(status, "added")
        self.assertEqual(len(journal), 2)


